ID: row.id,
Timestamp: row.timestamp,
},
MessageEvent: events.MessageEvent{
Body: row.body,
RawBody: row.body,
},
}
return message
}

func makeActionMessageChatEventFromRowData(row rowData) events.ActionEvent {
