}



func SetMessageVisibilityForUserID(userID string, visible bool) error {
defer func() {
_historyCache = nil
}()


ids := make([]string, 0)
query := "SELECT messages.id, user_id, body, title, subtitle, image, link, eventType, hidden_at, timestamp, display_name, display_color, created_at, disabled_at, previous_names, namechanged_at, authenticated_at, scopes, type FROM messages INNER JOIN users ON messages.user_id = users.id WHERE user_id = ?"
messages := getChat(query)

if len(messages) == 0 {
return nil
}

for _, message := range messages {
ids = append(ids, message.(events.UserMessageEvent).ID)
}


return SetMessagesVisibility(ids, visible)
}

func saveMessageVisibility(messageIDs []string, visible bool) error {
defer func() {
_historyCache = nil
}()

_datastore.DbLock.Lock()
defer _datastore.DbLock.Unlock()

tx, err := _datastore.DB.Begin()
if err != nil {
return err
}


stmt, err := tx.Prepare("UPDATE messages SET hidden_at=? WHERE id IN (?" + strings.Repeat(",?", len(messageIDs)-1) + ")")
if err != nil {
return err
}
defer stmt.Close()

var hiddenAt *time.Time
if !visible {
now := time.Now()
hiddenAt = &now
} else {
hiddenAt = nil
}

args := make([]interface{}, len(messageIDs)+1)
args[0] = hiddenAt
for i, id := range messageIDs {
args[i+1] = id
}

if _, err = stmt.Exec(args...); err != nil {
return err
}

if err = tx.Commit(); err != nil {
return err
}

return nil
}

