import (
"github.com/gin-gonic/gin"
"gorm.io/gorm"
)

func (c *Ctx[T]) SortOrder() func(db *gorm.DB) *gorm.DB {
return func(db *gorm.DB) *gorm.DB {
orderDirection := c.ctx.DefaultQuery("order", "desc")
fieldToSort := DefaultQuery(c.ctx, "sort_by", c.itemKey)


allowedFields := c.getAllowedSortFields()
if !isValidSortField(fieldToSort, allowedFields) {
fieldToSort = c.itemKey
}


if orderDirection != "asc" && orderDirection != "desc" {
orderDirection = "desc"
}

return db.Order(fmt.Sprintf("%s %s", fieldToSort, orderDirection))
}
}

func (c *Ctx[T]) OrderAndPaginate() func(db *gorm.DB) *gorm.DB {
return func(db *gorm.DB) *gorm.DB {
orderDir := c.ctx.DefaultQuery("order", "desc")
field := DefaultQuery(c.ctx, "sort_by", c.itemKey)


allowedFields := c.getAllowedSortFields()
if !isValidSortField(field, allowedFields) {
field = c.itemKey
}


if orderDir != "asc" && orderDir != "desc" {
orderDir = "desc"
}

result := db.Order(fmt.Sprintf("%s %s", field, orderDir))

_, offset, limit := GetPagingParams(c.ctx)
return result.Offset(offset).Limit(limit)
}
}

func DefaultValue(c *gin.Context, key string, defaultVal any) any {
if val, exists := c.Get(key); exists {
return val
}
return defaultVal
}

func DefaultQuery(c *gin.Context, key string, defaultVal any) string {
raw := DefaultValue(c, key, defaultVal)
return c.DefaultQuery(key, raw.(string))
}


func (c *Ctx[T]) getAllowedSortFields() []string {


return []string{"id", "created_at", "updated_at", c.itemKey}
}

func isValidSortField(field string, allowedFields []string) bool {
for _, allowed := range allowedFields {
if field == allowed {
return true
}
}
return false
}

