import (
"fmt"
"github.com/0xJacky/Nginx-UI/internal/logger"
"github.com/0xJacky/Nginx-UI/settings"
"github.com/gin-gonic/gin"
"github.com/spf13/cast"
"gorm.io/driver/sqlite"
"gorm.io/gen"
"gorm.io/gorm"
gormlogger "gorm.io/gorm/logger"
"path"
"strings"
"time"
)

var db *gorm.DB

type Model struct {
ID int `gorm:"primary_key" json:"id"`
CreatedAt time.Time `json:"created_at"`
UpdatedAt time.Time `json:"updated_at"`
DeletedAt *gorm.DeletedAt `gorm:"index" json:"deleted_at"`
}

func GenerateAllModel() []any {
return []any{
ConfigBackup{},
Auth{},
AuthToken{},
Cert{},
ChatGPTLog{},
Site{},
Stream{},
DnsCredential{},
Environment{},
Notification{},
}
}

func logMode() gormlogger.Interface {
switch settings.ServerSettings.RunMode {
case gin.ReleaseMode:
return gormlogger.Default.LogMode(gormlogger.Warn)
default:
fallthrough
case gin.DebugMode:
return gormlogger.Default.LogMode(gormlogger.Info)
}
}

func UseDB() *gorm.DB {
return db
}

func Init() *gorm.DB {
dir := path.Dir(settings.ConfPath)
dbFileName := fmt.Sprintf("%s.db", settings.ServerSettings.Database)
dbPath := path.Join(dir, dbFileName)

var err error
db, err = gorm.Open(sqlite.Open(dbPath), &gorm.Config{
Logger: logMode(),
PrepareStmt: true,
DisableForeignKeyConstraintWhenMigrating: true,
})

if err != nil {
logger.Fatal(err.Error())
}

if err = db.AutoMigrate(GenerateAllModel()...); err != nil {
logger.Fatal(err.Error())
}

return db
}

type Pagination struct {
Total int64 `json:"total"`
PerPage int `json:"per_page"`
CurrentPage int `json:"current_page"`
TotalPages int64 `json:"total_pages"`
}

type DataList struct {
Data interface{} `json:"data"`
Pagination Pagination `json:"pagination,omitempty"`
}

func SortOrder(c *gin.Context) func(db *gorm.DB) *gorm.DB {
return func(db *gorm.DB) *gorm.DB {
field := DefaultQuery(c, "sort_by", "id")
direction := c.DefaultQuery("order", "desc")
orderExpr := strings.Join([]string{field, direction}, " ")
return db.Order(orderExpr)
}
}

func OrderAndPaginate(c *gin.Context) func(db *gorm.DB) *gorm.DB {
return func(db *gorm.DB) *gorm.DB {
field := DefaultQuery(c, "sort_by", "id")
direction := c.DefaultQuery("order", "desc")
var orderBuilder strings.Builder
orderBuilder.WriteString("`")
orderBuilder.WriteString(field)
orderBuilder.WriteString("` ")
orderBuilder.WriteString(direction)
db = db.Order(orderBuilder.String())

page := cast.ToInt(c.DefaultQuery("page", "1"))
if page < 1 {
page = 1
}

pageSize := settings.ServerSettings.PageSize
if rawSize := c.Query("page_size"); rawSize != "" {
if parsedSize := cast.ToInt(rawSize); parsedSize > 0 {
pageSize = parsedSize
}
}

start := (page - 1) * pageSize
return db.Offset(start).Limit(pageSize)
}
}

func QueryToInSearch(c *gin.Context, db *gorm.DB, keys ...string) *gorm.DB {
for _, key := range keys {
queryVals := c.QueryArray(key + "[]")
if len(queryVals) == 0 {
queryVals = c.QueryArray(key)
}
if len(queryVals) == 0 {
continue
}

var condBuilder strings.Builder
_, _ = condBuilder.WriteString("`")
_, _ = condBuilder.WriteString(key)
_, _ = condBuilder.WriteString("` IN ?")

db = db.Where(condBuilder.String(), queryVals)
}
return db
}

func QueryToEqualSearch(c *gin.Context, db *gorm.DB, keys ...string) *gorm.DB {
for _, key := range keys {
queryVal := c.Query(key)
if queryVal == "" {
continue
}

var conditionBuilder strings.Builder
_, err := conditionBuilder.WriteString("`")
if err != nil {
logger.Error(err)
continue
}
_, err = conditionBuilder.WriteString(key)
if err != nil {
logger.Error(err)
continue
}
_, err = conditionBuilder.WriteString("` = ?")
if err != nil {
logger.Error(err)
continue
}

db = db.Where(conditionBuilder.String(), queryVal)
}
return db
}

func QueryToFussySearch(c *gin.Context, db *gorm.DB, keys ...string) *gorm.DB {
for _, v := range keys {
if c.Query(v) != "" {
var sb strings.Builder

_, err := fmt.Fprintf(&sb, "`%s` LIKE ?", v)
if err != nil {
logger.Error(err)
continue
}

var sbValue strings.Builder

_, err = fmt.Fprintf(&sbValue, "%%%s%%", c.Query(v))

if err != nil {
logger.Error(err)
continue
}

db = db.Where(sb.String(), sbValue.String())
}
}
return db
}

func QueryToFuzzySearch(c *gin.Context, db *gorm.DB, param string, fields ...string) *gorm.DB {
queryVal := c.Query(param)
if queryVal == "" {
return db
}

wrappedVal := "%" + queryVal + "%"
var clause *gorm.DB

for idx, field := range fields {
likeExpr := field + " LIKE ?"
if idx == 0 {
clause = db.Where(db.Where(likeExpr, wrappedVal))
} else {
clause = clause.Or(likeExpr, wrappedVal)
}
}

return db.Where(clause)
}

func QueryOrInFilter(c *gin.Context, db *gorm.DB, fields ...string) *gorm.DB {
for _, field := range fields {
values := c.QueryArray(field + "[]")
if len(values) == 0 {
values = c.QueryArray(field)
}
if len(values) > 0 {
cond := fmt.Sprintf("`%s` IN ?", field)
if cond == "" {
continue
}
db = db.Or(cond, values)
}
}
return db
}

func ApplyOrEqualFilters(c *gin.Context, db *gorm.DB, fields ...string) *gorm.DB {
for _, field := range fields {
val := c.Query(field)
if val == "" {
continue
}

condition := fmt.Sprintf("`%s` = ?", field)
db = db.Or(condition, val)
}
return db
}

