}

func (p *EventsPersister) GetEventTypes(userID uuid.UUID) (map[string]interface{}, error) {
result := map[string]interface{}{}
var categories []string
var actions []string


if err := p.DB.
Table("events").
Where("user_id = ?", userID).
Distinct("category").
Pluck("category", &categories).Error; err != nil {
return nil, err
}
result["category"] = categories


if err := p.DB.
Table("events").
Where("user_id = ?", userID).
Distinct("action").
Pluck("action", &actions).Error; err != nil {
return nil, err
}
result["action"] = actions

return result, nil
}

func (p *EventsPersister) GetAllEvents(filter *events.EventsFilter, userID uuid.UUID) (*EventsResponse, error) {
var result []*events.Event

query := p.DB.Model(&events.Event{}).Where("user_id = ?", userID)


if len(filter.Category) > 0 {
query = query.Where("category IN ?", filter.Category)
}
if len(filter.Action) > 0 {
query = query.Where("action IN ?", filter.Action)
}
if len(filter.Severity) > 0 {
query = query.Where("severity IN ?", filter.Severity)
}
if filter.Search != "" {
query = query.Where("description LIKE ?", "%"+filter.Search+"%")
}
if filter.Status != "" {
query = query.Where("status = ?", filter.Status)
}


if filter.Order == "asc" {
query = query.Order(clause.OrderByColumn{
Column: clause.Column{Name: filter.SortOn},
Desc: false,
})
} else {
query = query.Order(clause.OrderByColumn{
Column: clause.Column{Name: filter.SortOn},
Desc: true,
})
}


var total int64
if err := query.Count(&total).Error; err != nil {
return nil, err
}


if filter.Offset > 0 {
query = query.Offset(filter.Offset)
}
if filter.Limit > 0 {
query = query.Limit(filter.Limit)
}


if err := query.Scan(&result).Error; err != nil {
return nil, err
}


severityStats, err := p.getCountBySeverity(userID, filter.Status)
if err != nil {
return nil, err
}


return &EventsResponse{
Events: result,
PageSize: filter.Limit,
TotalCount: total,
CountBySeverityLevel: severityStats,
}, nil
}

func (p *EventsPersister) UpdateEventStatus(eventID uuid.UUID, newStatus string) (*events.Event, error) {

update := map[string]interface{}{"status": newStatus}
if err := p.DB.Model(&events.Event{}).Where("id = ?", eventID).Updates(update).Error; err != nil {
return nil, err
}


var updated events.Event
if err := p.DB.First(&updated, "id = ?", eventID).Error; err != nil {
return nil, err
}

return &updated, nil
