err = global.GVA_DB.Where("id = ?", id).Preload("JoinTemplate").Preload("Conditions").First(&sysExportTemplate).Error
return
}



func (svc *SysExportTemplateService) GetSysExportTemplateInfoList(req systemReq.SysExportTemplateSearch) ([]system.SysExportTemplate, int64, error) {
var (
templates []system.SysExportTemplate
total int64
)

pageSize := req.PageSize
pageOffset := pageSize * (req.Page - 1)

query := global.GVA_DB.Model(&system.SysExportTemplate{})


if req.StartCreatedAt != nil && req.EndCreatedAt != nil {
query = query.Where("created_at BETWEEN ? AND ?", req.StartCreatedAt, req.EndCreatedAt)
}
if req.Name != "" {
query = query.Where("name LIKE ?", "%"+req.Name+"%")
}
if req.TableName != "" {
query = query.Where("table_name = ?", req.TableName)
}
if req.TemplateID != "" {
query = query.Where("template_id = ?", req.TemplateID)
}


if err := query.Count(&total).Error; err != nil {
return nil, 0, err
}


if pageSize > 0 {
query = query.Limit(pageSize).Offset(pageOffset)
}


err := query.Find(&templates).Error
return templates, total, err
}

func (svc *SysExportTemplateService) ExportExcel(templateID string, values url.Values) (*bytes.Buffer, string, error) {
var template system.SysExportTemplate
if err := global.GVA_DB.Preload("Conditions").Preload("JoinTemplate").First(&template, "template_id = ?", templateID).Error; err != nil {
return nil, "", err
}

xlsx := excelize.NewFile()
defer func() {
if cerr := xlsx.Close(); cerr != nil {
fmt.Println(cerr)
}
}()

sheetIdx, err := xlsx.NewSheet("Sheet1")
if err != nil {
fmt.Println(err)
return nil, "", err
}

columns, err := utils.GetJSONKeys(template.TemplateInfo)
if err != nil {
return nil, "", err
}

var colMap map[string]string
if err := json.Unmarshal([]byte(template.TemplateInfo), &colMap); err != nil {
return nil, "", err
}

headers := make([]string, len(columns))
for i, key := range columns {
headers[i] = colMap[key]
}

rows := [][]string{headers}


db := global.GVA_DB
if template.DBName != "" {
db = global.MustGetGlobalDBByDBName(template.DBName)
}


selectClause := make([]string, len(columns))
for i, col := range columns {
selectClause[i] = fmt.Sprintf("`%s`", col)
}
db = db.Select(strings.Join(selectClause, ", ")).Table(template.TableName)


for _, join := range template.JoinTemplate {

db = db.Joins(fmt.Sprintf("%s`%s` ON %s = ?", join.JOINS, join.Table, join.ON), 1)
}


for _, cond := range template.Conditions {
val := values.Get(cond.From)
if val == "" {
continue
}
if cond.Operator == "LIKE" {
val = "%" + val + "%"
}
db = db.Where(fmt.Sprintf("`%s` %s ?", cond.Column, cond.Operator), val)
}


if limitStr := values.Get("limit"); limitStr != "" {
if limit, err := strconv.Atoi(limitStr); err == nil {
db = db.Limit(limit)
}
} else if template.Limit > 0 {
db = db.Limit(template.Limit)
}

if offsetStr := values.Get("offset"); offsetStr != "" {
if offset, err := strconv.Atoi(offsetStr); err == nil {
db = db.Offset(offset)
}
}


if order := values.Get("order"); order != "" {

if isValidOrderClause(order) {
db = db.Order(order)
}
} else if template.Order != "" {
if isValidOrderClause(template.Order) {
db = db.Order(template.Order)
}
}


var result []map[string]interface{}
if err := db.Find(&result).Error; err != nil {
return nil, "", err
}


for _, rowMap := range result {
row := make([]string, 0, len(columns))
for _, rawCol := range columns {
col := rawCol
if len(template.JoinTemplate) > 0 {
if parts := strings.Split(rawCol, " as "); len(parts) > 1 {
col = strings.TrimSpace(parts[1])
} else if parts := strings.Split(rawCol, "."); len(parts) > 1 {
col = parts[1]
}
}
row = append(row, fmt.Sprintf("%v", rowMap[col]))
}
rows = append(rows, row)
}


for rowIdx, row := range rows {
for colIdx, val := range row {
cell := fmt.Sprintf("%s%d", getColumnName(colIdx+1), rowIdx+1)
if err := xlsx.SetCellValue("Sheet1", cell, val); err != nil {
return nil, "", err
}
}
}

xlsx.SetActiveSheet(sheetIdx)
buffer, err := xlsx.WriteToBuffer()
if err != nil {
return nil, "", err
}
return buffer, template.Name, nil
}



func (svc *SysExportTemplateService) ExportTemplate(templateID string) (*bytes.Buffer, string, error) {
var tpl system.SysExportTemplate


if err := global.GVA_DB.First(&tpl, "template_id = ?", templateID).Error; err != nil {
return nil, "", err
}

excel := excelize.NewFile()
defer func() {
if cerr := excel.Close(); cerr != nil {
fmt.Println(cerr)
}
}()

sheet := "Sheet1"
index, err := excel.NewSheet(sheet)
if err != nil {
fmt.Println(err)
return nil, "", err
}


keys, err := utils.GetJSONKeys(tpl.TemplateInfo)
if err != nil {
return nil, "", err
}

var headerMap map[string]string
if err := json.Unmarshal([]byte(tpl.TemplateInfo), &headerMap); err != nil {
return nil, "", err
}


for i, key := range keys {
colName := getColumnName(i + 1)
if err := excel.SetCellValue(sheet, fmt.Sprintf("%s%d", colName, 1), headerMap[key]); err != nil {
return nil, "", err
}
}

excel.SetActiveSheet(index)

buffer, err := excel.WriteToBuffer()
if err != nil {
return nil, "", err
}

return buffer, tpl.Name, nil
}



func (svc *SysExportTemplateService) ImportExcel(templateID string, file *multipart.FileHeader) error {
var tpl system.SysExportTemplate
if err := global.GVA_DB.First(&tpl, "template_id = ?", templateID).Error; err != nil {
return err
}

srcFile, err := file.Open()
if err != nil {
return err
}
defer srcFile.Close()

excelFile, err := excelize.OpenReader(srcFile)
if err != nil {
return err
}

sheetRows, err := excelFile.GetRows("Sheet1")
if err != nil {
return err
}
if len(sheetRows) < 2 {
return errors.New("Excel 数据不足")
}


var fieldMap map[string]string
if err := json.Unmarshal([]byte(tpl.TemplateInfo), &fieldMap); err != nil {
return err
}


titleToKey := make(map[string]string)
for k, v := range fieldMap {
titleToKey[v] = k
}

db := global.GVA_DB
if tpl.DBName != "" {
db = global.MustGetGlobalDBByDBName(tpl.DBName)
}

return db.Transaction(func(tx *gorm.DB) error {
header := sheetRows[0]
dataRows := sheetRows[1:]

records := make([]map[string]interface{}, 0, len(dataRows))
for _, row := range dataRows {
entry := make(map[string]interface{})
for colIdx, val := range row {
if colIdx >= len(header) {
continue
}
if key, ok := titleToKey[header[colIdx]]; ok {
entry[key] = val
}
}


if tx.Migrator().HasColumn(tpl.TableName, "created_at") && entry["created_at"] == nil {
entry["created_at"] = time.Now()
}
if tx.Migrator().HasColumn(tpl.TableName, "updated_at") && entry["updated_at"] == nil {
entry["updated_at"] = time.Now()
}

records = append(records, entry)
}

return tx.Table(tpl.TableName).CreateInBatches(&records, 1000).Error
})
}

func getColumnName(n int) string {
columnName := ""
for n > 0 {
n--
columnName = string(rune('A'+n%26)) + columnName
n /= 26
}
return columnName
}


func isValidOrderClause(order string) bool {
if order == "" {
return false
}

for _, c := range order {
if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == ' ' || c == ',' || c == '.') {
return false
}
}
return true
}

