countQuestions: function(callback) {
connection.query('SELECT COUNT(*) AS cntQuestion FROM Question WHERE status=1 AND surveyId=?', [id], function(err, rows) {
if (err) {
callback({ code: 500, msg: err.message });
return;
}
if (!rows.length) {
callback({ code: 404, msg: 'Survey not found' });
return;
}
questionCount = rows[0].cntQuestion;
callback(null);
});
},
validateAndUpdate: function(callback) {
if (Object.keys(body).length < questionCount) {
connection.query(baseSql, [id], function(err, rows) {
if (err) {
callback({ code: 500, msg: err.message });
return;
}
res.render('survey.html', {
msg: 'Please answer all questions',
cache: body,
data: hashfyQuery(rows)
});
callback(null);
});
} else {
const placeholders = itemIds.map(() => '?').join(',');
const updateSql = `UPDATE Item SET count=count+1 WHERE id IN (${placeholders})`;
