function hashfyQuery(rows) {
var res = {};
res.sid = rows[0].sid;
res.stitle = rows[0].stitle;
res.sdesc = rows[0].sdesc;
res.holder = 'admin';
res.category = rows[0].categoryId;
res.titleExcept = null;
res.cntQuestionExcept = null;

var questions = [];
for (var i = 0; i < rows.length; i++) {
if (i == 0 || rows[i].qid != rows[i - 1].qid) {
var q = {};
q.qid = rows[i].qid;
q.question = rows[i].question;
q.items = [];
q.questionExcept = null;
q.cntItemExcept = null;

var total = 0;
var j = i;
while (j < rows.length && rows[j].qid == rows[i].qid) {
total += rows[j].icnt;
j++;
}
q.total = total;

var it = {};
it.iid = rows[i].iid;
it.item = rows[i].item;
it.icnt = rows[i].icnt;
it.percent = (q.total > 0) ? Math.round(it.icnt / q.total * 100) : 0;
q.items.push(it);

questions.push(q);
} else {
var q = questions[questions.length - 1];
var it = {};
it.iid = rows[i].iid;
it.item = rows[i].item;
it.icnt = rows[i].icnt;
it.percent = (q.total > 0) ? Math.round(it.icnt / q.total * 100) : 0;
it.itemExcept = null;
q.items.push(it);
}
}
res.questions = questions;
return res;
}


