* @param request The http request
* @param response The http response
* @param action The function to be ran once the body is read
*/
function handlePost(req, res, actionHandler) {
res.statusCode = 200;
res.setHeader('Access-Control-Allow-Origin', 'http:
res.setHeader('Access-Control-Allow-Methods', 'POST');
res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

let payload = '';

req.on('data', chunk => {
payload += chunk;
});

req.on('error', err => {
console.error('Post error occurred:', err);
res.statusCode = 400;
res.end();
});

req.on('end', () => {
if (payload && payload.length > 0) {
try {
const parsed = JSON.parse(payload);
actionHandler(req, res, parsed);
} catch (e) {
res.statusCode = 400;
res.end('Invalid JSON');
}
} else {
res.end();
}
});
}

