* into and object, to simplify code but only way I was skilled enough to was
* first select 'tests' then manually add 'notes' to them with another
* select statement.
* @param response Response to write the tests to
* @param tests Array of tests from the DB
*/
function getAddNotesToTests(response, tests, table){
var notes = [];
var notesTable = 'notes_' + table.substring(6);
var query = connection.query('SELECT * FROM ??', [notesTable], function(err, rows, fields) {
if (err) {
console.log(err);
} else {
for(var i = 0; i < rows.length; i++){
notes[i] = rows[i];
}
}
});

query.on('end',function(){
for(var i = 0; i < tests.length; i++){
var test = tests[i];
for(var j = 0; j < notes.length; j++){
var note = notes[j];
if(note.testId === test.id){
test.notes.push(note);
}
}
}
response.write(JSON.stringify(tests));
response.end();
});
}

/**
* Gets the tables in the database to fill the projects drop down
* @param response Response to return
*/
function getProjectTables(res) {
const results = [];


const queryStr = "SELECT TABLE_NAME as project FROM information_schema.tables WHERE TABLE_NAME LIKE 'test_%'";

const q = connection.query(queryStr, function(error, dataRows) {
if (error) {
console.log("Database query failed:", error);
} else {
dataRows.forEach(function(row, index) {
results[index] = row;
});
}
});

q.on('end', function() {
for (let j = 0; j < results.length; j++) {
const entry = results[j];
const newEntry = {};
newEntry.db = entry.project;
newEntry.name = entry.project.slice(6);
results[j] = newEntry;
}

const jsonResp = JSON.stringify(results);
res.write(jsonResp);
res.end();
});
}

