func getChat(query string) []interface{} {
result := make([]interface{}, 0)

dataRows, queryErr := _datastore.DB.Query(query)
if queryErr != nil || dataRows.Err() != nil {
log.Errorln("error fetching chat history", queryErr)
return result
}
defer dataRows.Close()

for dataRows.Next() {
var record rowData

scanErr := dataRows.Scan(
&record.id,
&record.userID,
&record.body,
&record.title,
&record.subtitle,
&record.image,
&record.link,
&record.eventType,
&record.hiddenAt,
&record.timestamp,
&record.userDisplayName,
&record.userDisplayColor,
&record.userCreatedAt,
&record.userDisabledAt,
&record.previousUsernames,
&record.userNameChangedAt,
&record.userAuthenticatedAt,
&record.userScopes,
&record.userType,
)
if scanErr != nil {
log.Errorln(scanErr)
log.Errorln("Failed to convert DB result to chat object, query was:", query)
break
}

var msg interface{}

if record.eventType == events.MessageSent {
msg = makeUserMessageEventFromRowData(record)
} else if record.eventType == events.SystemMessageSent {
msg = makeSystemMessageChatEventFromRowData(record)
} else if record.eventType == events.ChatActionSent {
msg = makeActionMessageChatEventFromRowData(record)
} else if record.eventType == events.FediverseEngagementFollow ||
record.eventType == events.FediverseEngagementLike ||
record.eventType == events.FediverseEngagementRepost {
msg = makeFederatedActionChatEventFromRowData(record)
}

result = append(result, msg)
}

return result
}

