import (
"fmt"
"strings"
"time"

"github.com/owncast/owncast/core/chat/events"
"github.com/owncast/owncast/core/data"
"github.com/owncast/owncast/core/user"
"github.com/owncast/owncast/models"
log "github.com/sirupsen/logrus"
)

var _datastore *data.Datastore

const (
maxBacklogHours = 2
maxBacklogNumber = 50
)

func setupPersistence() {
_datastore = data.GetDatastore()
data.CreateMessagesTable(_datastore.DB)
data.CreateBanIPTable(_datastore.DB)

chatDataPruner := time.NewTicker(5 * time.Minute)
go func() {
runPruner()
for range chatDataPruner.C {
runPruner()
}
}()
}


func SaveUserMessage(event events.UserMessageEvent) {
saveEvent(event.ID, &event.User.ID, event.Body, event.Type, event.HiddenAt, event.Timestamp, nil, nil, nil, nil)
}

func saveFederatedAction(event events.FediverseEngagementEvent) {
saveEvent(event.ID, nil, event.Body, event.Type, nil, event.Timestamp, event.Image, &event.Link, &event.UserAccountName, nil)
}


func saveEvent(id string, userID *string, body string, eventType string, hidden *time.Time, timestamp time.Time, image *string, link *string, title *string, subtitle *string) {
defer func() {
_historyCache = nil
}()

tx, err := _datastore.DB.Begin()
if err != nil {
log.Errorln("error saving", eventType, err)
return
}

defer tx.Rollback()

stmt, err := tx.Prepare("INSERT INTO messages(id, user_id, body, eventType, hidden_at, timestamp, image, link, title, subtitle) values(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
if err != nil {
log.Errorln("error saving", eventType, err)
return
}

defer stmt.Close()

if _, err = stmt.Exec(id, userID, body, eventType, hidden, timestamp, image, link, title, subtitle); err != nil {
log.Errorln("error saving", eventType, err)
return
}
if err = tx.Commit(); err != nil {
log.Errorln("error saving", eventType, err)
return
}
}

func makeUserMessageEventFromRowData(row rowData) events.UserMessageEvent {
scopes := ""
if row.userScopes != nil {
scopes = *row.userScopes
}

previousUsernames := []string{}
if row.previousUsernames != nil {
previousUsernames = strings.Split(*row.previousUsernames, ",")
}

displayName := ""
if row.userDisplayName != nil {
displayName = *row.userDisplayName
}

displayColor := 0
if row.userDisplayColor != nil {
displayColor = *row.userDisplayColor
}

createdAt := time.Time{}
if row.userCreatedAt != nil {
createdAt = *row.userCreatedAt
}

isBot := (row.userType != nil && *row.userType == "API")
scopeSlice := strings.Split(scopes, ",")

u := user.User{
ID: *row.userID,
DisplayName: displayName,
DisplayColor: displayColor,
CreatedAt: createdAt,
DisabledAt: row.userDisabledAt,
NameChangedAt: row.userNameChangedAt,
PreviousNames: previousUsernames,
AuthenticatedAt: row.userAuthenticatedAt,
Authenticated: row.userAuthenticatedAt != nil,
Scopes: scopeSlice,
IsBot: isBot,
}

message := events.UserMessageEvent{
Event: events.Event{
Type: row.eventType,
ID: row.id,
Timestamp: row.timestamp,
},
UserEvent: events.UserEvent{
User: &u,
HiddenAt: row.hiddenAt,
},
MessageEvent: events.MessageEvent{
Body: row.body,
RawBody: row.body,
},
}

return message
}

func makeSystemMessageChatEventFromRowData(row rowData) events.SystemMessageEvent {
message := events.SystemMessageEvent{
Event: events.Event{
Type: row.eventType,
ID: row.id,
Timestamp: row.timestamp,
},
MessageEvent: events.MessageEvent{
Body: row.body,
RawBody: row.body,
},
}
return message
}

func makeActionMessageChatEventFromRowData(row rowData) events.ActionEvent {
message := events.ActionEvent{
Event: events.Event{
Type: row.eventType,
ID: row.id,
Timestamp: row.timestamp,
},
MessageEvent: events.MessageEvent{
Body: row.body,
RawBody: row.body,
},
}
return message
}

func makeFederatedActionChatEventFromRowData(record rowData) events.FediverseEngagementEvent {
var evt events.FediverseEngagementEvent

evt.Event.Type = record.eventType
evt.Event.ID = record.id
evt.Event.Timestamp = record.timestamp

evt.MessageEvent.Body = record.body
evt.MessageEvent.RawBody = record.body

evt.Image = record.image
evt.Link = *record.link
evt.UserAccountName = *record.title

return evt
}

type rowData struct {
id string
userID *string
body string
eventType models.EventType
hiddenAt *time.Time
timestamp time.Time
title *string
subtitle *string
image *string
link *string

userDisplayName *string
userDisplayColor *int
userCreatedAt *time.Time
userDisabledAt *time.Time
previousUsernames *string
userNameChangedAt *time.Time
userAuthenticatedAt *time.Time
userScopes *string
userType *string
}

func getChat(query string) []interface{} {
result := make([]interface{}, 0)

dataRows, queryErr := _datastore.DB.Query(query)
if queryErr != nil || dataRows.Err() != nil {
log.Errorln("error fetching chat history", queryErr)
return result
}
defer dataRows.Close()

for dataRows.Next() {
var record rowData

scanErr := dataRows.Scan(
&record.id,
&record.userID,
&record.body,
&record.title,
&record.subtitle,
&record.image,
&record.link,
&record.eventType,
&record.hiddenAt,
&record.timestamp,
&record.userDisplayName,
&record.userDisplayColor,
&record.userCreatedAt,
&record.userDisabledAt,
&record.previousUsernames,
&record.userNameChangedAt,
&record.userAuthenticatedAt,
&record.userScopes,
&record.userType,
)
if scanErr != nil {
log.Errorln(scanErr)
log.Errorln("Failed to convert DB result to chat object, query was:", query)
break
}

var msg interface{}

if record.eventType == events.MessageSent {
msg = makeUserMessageEventFromRowData(record)
} else if record.eventType == events.SystemMessageSent {
msg = makeSystemMessageChatEventFromRowData(record)
} else if record.eventType == events.ChatActionSent {
msg = makeActionMessageChatEventFromRowData(record)
} else if record.eventType == events.FediverseEngagementFollow ||
record.eventType == events.FediverseEngagementLike ||
record.eventType == events.FediverseEngagementRepost {
msg = makeFederatedActionChatEventFromRowData(record)
}

result = append(result, msg)
}

return result
}

var _historyCache *[]interface{}


func GetChatModerationHistory() []interface{} {
cacheExists := _historyCache != nil
if cacheExists {
return *_historyCache
}

sqlQuery := "SELECT messages.id, user_id, body, title, subtitle, image, link, eventType, hidden_at, timestamp, display_name, display_color, created_at, disabled_at, previous_names, namechanged_at, authenticated_at, scopes, type FROM messages INNER JOIN users ON messages.user_id = users.id ORDER BY timestamp DESC"
chatRecords := getChat(sqlQuery)

_historyCache = &chatRecords

return chatRecords
}



func GetChatHistory() []interface{} {

query := fmt.Sprintf("SELECT messages.id, messages.user_id, messages.body, messages.title, messages.subtitle, messages.image, messages.link, messages.eventType, messages.hidden_at, messages.timestamp, users.display_name, users.display_color, users.created_at, users.disabled_at, users.previous_names, users.namechanged_at, users.authenticated_at, users.scopes, users.type FROM users JOIN messages ON users.id = messages.user_id WHERE hidden_at IS NULL AND disabled_at IS NULL ORDER BY timestamp DESC LIMIT %d", maxBacklogNumber)
m := getChat(query)


for i, j := 0, len(m)-1; i < j; i, j = i+1, j-1 {
m[i], m[j] = m[j], m[i]
}

return m
}



func SetMessageVisibilityForUserID(userID string, visible bool) error {
defer func() { _historyCache = nil }()

baseQuery := "SELECT messages.id, user_id, body, title, subtitle, image, link, eventType, hidden_at, timestamp, display_name, display_color, created_at, disabled_at, previous_names, namechanged_at, authenticated_at, scopes, type FROM messages INNER JOIN users ON messages.user_id = users.id"
filterClause := " WHERE user_id = ?"
fullQuery := baseQuery + filterClause

userMessages := getChat(fullQuery, userID)

if len(userMessages) == 0 {
return nil
}

collectedIDs := make([]string, 0, len(userMessages))
for _, msg := range userMessages {
userMsg := msg.(events.UserMessageEvent)
collectedIDs = append(collectedIDs, userMsg.ID)
}

return SetMessagesVisibility(collectedIDs, visible)
}


func saveMessageVisibility(messageIDs []string, visible bool) error {
defer func() {
_historyCache = nil
}()

_datastore.DbLock.Lock()
defer _datastore.DbLock.Unlock()

tx, err := _datastore.DB.Begin()
if err != nil {
return err
}


stmt, err := tx.Prepare("UPDATE messages SET hidden_at=? WHERE id IN (?" + strings.Repeat(",?", len(messageIDs)-1) + ")")
if err != nil {
return err
}
defer stmt.Close()

var hiddenAt *time.Time
if !visible {
now := time.Now()
hiddenAt = &now
} else {
hiddenAt = nil
}

args := make([]interface{}, len(messageIDs)+1)
args[0] = hiddenAt
for i, id := range messageIDs {
args[i+1] = id
}

if _, err = stmt.Exec(args...); err != nil {
return err
}

if err = tx.Commit(); err != nil {
return err
}

return nil
}

